import re
import sys

# Increase recursion depth just in case of deep chains
sys.setrecursionlimit(5000)

def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    # Token specification
    # Operators: <=, >=, <>, =, <, >, +, -, *, /, :, ,, (, )
    # Functions: SUM, MIN, MAX, IF
    # Cell: [A-Z][1-9][0-9]?
    # Number: [0-9]+
    token_re = re.compile(
        r'\s*(<=|>=|<>|=|<|>|\+|-|\*|/|:|,|\(|\)|[A-Z]+[0-9]*|[0-9]+)\s*'
    )

    memo: dict[str, int | str] = {}
    evaluating: set[str] = set()

    def eval_cell(name: str) -> int | str:
        if name not in cells:
            return 0
        if name in memo:
            return memo[name]
        if name in evaluating:
            return "#CYCLE!"

        evaluating.add(name)
        content = cells[name].strip()
        val = eval_content(content)
        evaluating.remove(name)
        memo[name] = val
        return val

    def eval_content(content: str) -> int | str:
        if not content.startswith('='):
            return int(content)
        tokens = token_re.findall(content[1:])
        pos = 0

        def peek() -> str | None:
            nonlocal pos
            return tokens[pos] if pos < len(tokens) else None

        def consume(expected: str | None = None) -> str:
            nonlocal pos
            t = tokens[pos]
            if expected is not None and t != expected:
                raise ValueError(f"Expected {expected}, got {t}")
            pos += 1
            return t

        def parse_formula() -> int | str:
            val = parse_term()
            if isinstance(val, str):
                return val
            while peek() in ('+', '-'):
                op = consume()
                right = parse_term()
                if isinstance(right, str):
                    return right
                if op == '+':
                    val += right
                else:
                    val -= right
            return val

        def parse_term() -> int | str:
            val = parse_unary()
            if isinstance(val, str):
                return val
            while peek() in ('*', '/'):
                op = consume()
                right = parse_unary()
                if isinstance(right, str):
                    return right
                if op == '*':
                    val *= right
                else:
                    if right == 0:
                        return "#DIV/0!"
                    # Truncate toward zero
                    if (val < 0) ^ (right < 0):
                        val = - (abs(val) // abs(right))
                    else:
                        val = abs(val) // abs(right)
            return val

        def parse_unary() -> int | str:
            minus_count = 0
            while peek() == '-':
                consume()
                minus_count += 1
            val = parse_atom()
            if isinstance(val, str):
                return val
            if minus_count % 2 == 1:
                val = -val
            return val

        def parse_atom() -> int | str:
            tok = peek()
            if tok == '(':
                consume('(')
                val = parse_formula()
                if isinstance(val, str):
                    return val
                consume(')')
                return val
            elif tok in ('SUM', 'MIN', 'MAX'):
                fn = consume()
                consume('(')
                values: list[int] = []
                first_error: str | None = None

                while True:
                    # Check if next tokens form a range X1:Y2
                    is_range = False
                    if pos + 2 < len(tokens) and tokens[pos + 1] == ':':
                        t1 = tokens[pos]
                        t2 = tokens[pos + 2]
                        if is_cell_name(t1) and is_cell_name(t2):
                            is_range = True

                    if is_range:
                        start_cell = consume()
                        consume(':')
                        end_cell = consume()

                        if first_error is None:
                            c1, r1 = parse_cell_name(start_cell)
                            c2, r2 = parse_cell_name(end_cell)
                            col_start, col_end = min(c1, c2), max(c1, c2)
                            row_start, row_end = min(r1, r2), max(r1, r2)

                            for r in range(row_start, row_end + 1):
                                for c in range(col_start, col_end + 1):
                                    c_name = f"{chr(ord('A') + c)}{r}"
                                    if c_name in cells:
                                        res = eval_cell(c_name)
                                        if isinstance(res, str):
                                            first_error = res
                                            break
                                        values.append(res)
                                if first_error is not None:
                                    break
                    else:
                        res = parse_formula()
                        if first_error is None:
                            if isinstance(res, str):
                                first_error = res
                            else:
                                values.append(res)

                    if peek() == ',':
                        consume(',')
                    else:
                        break

                consume(')')
                if first_error is not None:
                    return first_error

                if fn == 'SUM':
                    return sum(values) if values else 0
                elif fn == 'MIN':
                    return min(values) if values else 0
                elif fn == 'MAX':
                    return max(values) if values else 0

            elif tok == 'IF':
                consume('IF')
                consume('(')

                # left OP right
                left_val = parse_formula()
                if isinstance(left_val, str):
                    return left_val

                op = consume()
                right_val = parse_formula()
                if isinstance(right_val, str):
                    return right_val

                cond: bool
                if op == '=':
                    cond = (left_val == right_val)
                elif op == '<>':
                    cond = (left_val != right_val)
                elif op == '<':
                    cond = (left_val < right_val)
                elif op == '<=':
                    cond = (left_val <= right_val)
                elif op == '>':
                    cond = (left_val > right_val)
                elif op == '>=':
                    cond = (left_val >= right_val)
                else:
                    raise ValueError(f"Unknown operator {op}")

                consume(',')
                # parse then branch or skip it
                if cond:
                    then_val = parse_formula()
                    consume(',')
                    skip_formula()
                    consume(')')
                    return then_val
                else:
                    skip_formula()
                    consume(',')
                    else_val = parse_formula()
                    consume(')')
                    return else_val

            elif is_cell_name(tok):
                name = consume()
                return eval_cell(name)
            elif tok.isdigit():
                return int(consume())
            else:
                raise ValueError(f"Unexpected token {tok}")

        def skip_formula():
            # Skip until a comma or matching closing parenthesis at balance 0
            paren = 0
            while pos < len(tokens):
                t = tokens[pos]
                if t == '(':
                    paren += 1
                elif t == ')':
                    if paren == 0:
                        break
                    paren -= 1
                elif t == ',' and paren == 0:
                    break
                pos += 1

        return parse_formula()

    def is_cell_name(tok: str | None) -> bool:
        if not tok or len(tok) < 2 or len(tok) > 3:
            return False
        if not ('A' <= tok[0] <= 'Z'):
            return False
        digits = tok[1:]
        if not digits.isdigit():
            return False
        if digits.startswith('0'):
            return False
        row = int(digits)
        return 1 <= row <= 99

    def parse_cell_name(name: str) -> tuple[int, int]:
        col = ord(name[0]) - ord('A')
        row = int(name[1:])
        return col, row

    # Evaluate all cells defined in `cells`
    for name in cells:
        eval_cell(name)

    return {name: memo[name] for name in cells}
